#!/usr/bin/env python3
import json,pathlib
r=pathlib.Path(__file__).resolve().parent
A=[json.loads((r/f'results/cohort{c}/absolute.json').read_text()) for c in [0,1]]
P=[json.loads((r/f'results/cohort{c}/pairs.json').read_text()) for c in [0,1]]
def av(c,case,role,m):return next(x for x in A[c] if (x['case'],x['role'],x['metric'])==(case,role,m))
def pv(c,case,l,rr,m):return next(x for x in P[c] if (x['case'],x['left'],x['right'],x['metric'])==(case,l,rr,m))
def abscols(case,role,m):return ' / '.join(f"{av(c,case,role,m)['median']:.4f}" for c in [0,1])
def pct(case,l='B',rr='C9',m='backend_cpu_ms'):return ' / '.join(f"{pv(c,case,l,rr,m)['percent']['median']:+.2f}" for c in [0,1])
checks=json.loads((r/'evidence/FINAL-CHECKS-final-r1.json').read_text());assert checks['status']=='PASS' and checks['cluster_directories_checked']==15
cases=['am_inline','am_absent','am_skew1000','am_full','am_or','am_dense','am_rare']
assert all(pv(c,case,'B','C9','am_loop_cpu_ms')['percent']['median']<0 for c in [0,1] for case in cases)
lines=['# GIN C9: repaired targets and addressed control repetitions','', 'C9 fixes the measured native inline penalty and the absent cost while preserving large selective SQL gains. In a new same-source diagnostic, OR, dense AND and single-rare AM CPU improve in both reversed cohorts; unchanged OR/rare SQL controls improve too. Earlier full-SQL positive movements remain valid unresolved observations. No additional PostgreSQL source change was justified by this diagnostic, and no universal or current-master speedup is claimed.','', 'Source remains 0ab3bd65c8957ea5e25f9ef8981401f0616d99de, experiments/gin-combined-v9-b72-20261110. Baseline is fixed B72 (72b9498df9a369e747f8d96efb5a6cd33c2451e2 plus the same prerequisite), fixed base8a8c475037bfde101da23cc9b0364c9c020eca93. The complete same C9 diff and its prior artifact verification are included. All code branches and failed earlier alternatives remain preserved.','', '## New real-AM CPU measurements','', 'Each entry is cohort0 / cohort1, kept separate. Absolute columns and paired percentages both use internal process CPU for real index_rescan/index_getbitmap/tbm_free loops. Percentages are medians of direct same-round ratios, not ratios of aggregate medians. These are not SQL throughput or heap visibility.','', '| Case | B CPU ms | L4 CPU ms | C9 CPU ms | C9/B % | C9/T % | C9/L4 % |','|---|---:|---:|---:|---:|---:|---:|']
for case in cases:
 lines.append('| '+' | '.join([case]+[abscols(case,role,'am_loop_cpu_ms') for role in ['B','L4','C9']]+[pct(case,l,'C9','am_loop_cpu_ms') for l in ['B','T','L4']])+' |')
lines+=['','## New SQL controls','', 'Absolute medians are EXPLAIN executor ms. Paired percentages are whole-command backend CPU, a separate boundary. Commands/data are unchanged.','', '| Case | B executor ms | C9 executor ms | C9/B CPU % | T/B CPU % | C9/T CPU % | C9/L4 CPU % |','|---|---:|---:|---:|---:|---:|---:|']
for case in ['or_forced','single_rare','inline','seq_control']:
 lines.append('| '+' | '.join([case]+[abscols(case,role,'sql_execution_ms') for role in ['B','C9']]+[pct(case,l,rr) for l,rr in [('B','C9'),('B','T'),('T','C9'),('L4','C9')]])+' |')
lines+=['','Seq changes sign (-9.31/+7.90% versus B); L4 also changes -1.58/+10.28%. Keep those data as off-path/control variability, without claiming a proven harmless cause or an algorithmic cause. No baseline-twin normalization is applied. The new OR/rare results do not erase the earlier full-SQL positives.','', '## Earlier complete 25-case SQL campaign','', 'These are previously executed R3 observations, not new diagnostic results or pooled cohorts. The full immutable packet contains all 25 cases, all metrics, every pair/raw chronology and failed alternatives. HISTORICAL-R3.json pins this summary and its raw hashes/manifest. Absolute medians here are executor ms; percentages are paired backend CPU.','', '| Case | B executor ms | C9 executor ms | C9/B CPU % |','|---|---:|---:|---:|']
h=json.loads((r/'HISTORICAL-R3.json').read_text())
for case in ['skew1000','skew127','jsonb','intarray','builtin_array','skew_group4096','inline','absent','or_forced','single_rare','seq_control']:
 aa=[]
 for role in ['B','C9']:
  aa.append(' / '.join(f"{next(x for x in h['cohorts'][str(c)]['absolute'] if (x['case'],x['role'],x['metric'])==(case,role,'sql_execution_ms'))['median']:.4f}" for c in [0,1]))
 v=' / '.join(f"{next(x for x in h['cohorts'][str(c)]['pairs'] if (x['case'],x['left'],x['right'],x['metric'])==(case,'B','C9','backend_cpu_ms'))['percent']['median']:+.2f}" for c in [0,1])
 lines.append('| '+' | '.join([case]+aa+[v])+' |')
lines+=['','The historical inline SQL result is mixed versus B (+1.79/-4.94%) but improves versus L4 (-4.83/-8.96%). The diagnostic gives -0.11/-5.29% versus B and -8.00/-8.49% versus L4; native inline improves about 17% versus B and25% versus L4 in both diagnostic cohorts. These boundaries and experiments must stay separate.','', 'The earlier OR (+10.73/+1.75%) and single-rare (+3.49/+2.34%) full-SQL costs are retained. They were not repeated in the address-specific SQL runs and no positive inner-AM cost repeats there. That narrows the evidence for another source edit; it does not prove the older SQL differences harmless. Keep the prototype experimental and check representative workloads before proposing a merge.','', '## Spread and checks','', '| Cohort | AM case | B CPU min / median / max ms | C9 CPU min / median / max ms |','|---:|---|---:|---:|']
for c in [0,1]:
 for case in ['am_inline','am_absent','am_or','am_dense','am_rare']:
  cells=[]
  for role in ['B','C9']:
   x=av(c,case,role,'am_loop_cpu_ms');cells.append(' / '.join(f'{x[k]:.6f}' for k in ['min','median','max']))
  lines.append('| '+' | '.join([str(c),case]+cells)+' |')
lines+=['','All absolute min/median/max, sample SD/MAD, native CPU/wall, SQL executor/whole-command CPU/client wall and all six direct pairs remain in results/cohort*/tables and JSON. Exact raw observations/status/oracles and software stacks are in evidence/run-r1. Independent local reconstruction matches both remote analyses, with only relative3e-15 cross-Python sample-SD rounding tolerated. No trimming,pooling or twin correction.','', '- New work reused the checked R3 build installations. No new PostgreSQL code/build/core-test execution is claimed. Prior eleven builds each passed original239 tests; new qualification repeats all 25 ordered Seq/GIN multiset/scalar/path checks and eight prepared comparisons/cached rescans on all six builds, plus seven exact AM answers per build. C9_assert checks exact first-page counts by independent decoding. All25 multisets repeat per timed role/cohort.','- VM158, same GCC13.3 release flags -O2 -g -fno-lto, no ICU/readline, OpenSSL. Four roles B/T/L4/C9, exact B/T ELF, two warm+12 retained balanced rounds per case, two fresh CPU0/4→4/0 cohorts with reversed slots/session births/case order. New totals1232 raw / 1056 retained / 176 warm. JIT/parallel/memoize/autovacuum off,512MB shared_buffers,system timing clock. Every measured call follows an extra literal-answer execution. All retained recorded IO/WAL and backend read/write byte counters are zero.','- Six separate original-query software profiles of B/C9 OR,rare,Seq passed before fresh timing clusters. They are diagnostic software samples, not PMU attribution or paired timings. No host configuration or foreign workload was changed. No archive database was used.','- Final collector verifies all15 own new cluster directories shut down, eight measured backend PIDs/sockets absent, all six reference installs/final7726-source inventory/seed/frozen runtime/AM module unchanged, and no process using owned install/build executables. The supervisor PIPELINE pending-collection status is an earlier checkpoint; FINAL-CHECKS and CLOSEOUT record successful later collection/reconstruction.','', 'REPRODUCE.md contains exact source/setup/dependency/build/new-run commands and all seven AM loop counts. The same full candidate .diff is in patches/; this is not a new patch to stack. The English addendum is unsent. Prior-art scope remains bounded in PRIOR-ART.md, with no priority claim. No CREATE INDEX,current-master,independent-host confidence or general-regression-free claim.']
(r/'RESULTS.md').write_text('\n'.join(lines)+'\n')
draft=['Subject: GIN adaptive/lazy scans: OR and startup control follow-up','Status: UNSENT ADDENDUM TO THE MAIN DRAFT','', 'Hi,','', 'I repeated the remaining OR and single-rare SQL controls and added direct real-AM loops for OR, dense AND and single rare. PostgreSQL source/builds stayed at C9; this is not another patch to stack. The same complete C9 diff is included for convenience.','', 'The earlier full25 SQL comparison had C9/B backend CPU +10.73/+1.75% for OR and +3.49/+2.34% for single rare. Those observations remain in the report. In this separate finite diagnostic, the unchanged SQL commands give '+pct('or_forced')+'% for OR and '+pct('single_rare')+'% for single rare.','', 'New actual-AM loop CPU medians, cohort0 / cohort1:','case | B ms | C9 ms | C9/B paired CPU %']
for case in cases:draft.append(' | '.join([case,abscols(case,'B','am_loop_cpu_ms'),abscols(case,'C9','am_loop_cpu_ms'),pct(case,m='am_loop_cpu_ms')]))
draft+=['', 'The native loop uses real index_rescan/index_getbitmap/tbm_free, actual public server headers and the correct F_TS_MATCH_VQ key. It has no private modeled loader. Native CPU/wall is separate from full SQL executor/whole-command CPU/client wall. The new OR/dense/rare loops do not show a repeated inner-AM cost. This does not explain away the historical SQL positives. Seq still changes sign (-9.31/+7.90% versus B), and no source-cause or harmless-noise explanation is claimed.','', 'The original regression repairs remain: native inline is about 17% faster than B (about 25% versus lazy V4), absent CPU improves about 87% in the AM loop and 63–67% in the preceding full-SQL comparison, while selective SQL gains are preserved. Full-SQL inline versus B was mixed (+1.79/-4.94%); the new unchanged inline SQL repeat gives -0.11/-5.29%. Experiments/metrics/cohorts are kept separate, not pooled or normalized by the identical binary twin.','', 'Same VM158 and checked fixed-B72 build set, GCC 13.3, -O2 -g -fno-lto, OpenSSL, no ICU/readline; no new code/build/core-test execution in this addendum. The existing builds passed 239 original tests each. This diagnostic repeats all 25 ordered Seq/GIN multisets/scalars/paths and prepared rescans on all six builds, adds seven AM answers per build, then runs four roles with two warm+12 retained balanced rounds in each of two reversed cohorts:1232 raw / 1056 retained / 176 warm. All own clusters stop cleanly and source/install/seed/runtime/module identities match.','', 'The packet includes the same .diff, raw data, absolute ranges, SD/MAD, every direct pair, software-stack diagnostics, exact revision/flags/dependencies/setup and both native/SQL reproduction commands in REPRODUCE.md. The concrete contribution remains the known-algorithm GIN integration and exact first-page cardinality preservation; no priority, current-master or CREATE INDEX claim is made. The fast-scan and extraction-series references are unchanged in PRIOR-ART.md [1,2].','', 'Code: https://github.com/pg-sharding/cpg/tree/experiments/gin-combined-v9-b72-20261110','Prior full results: https://github.com/pg-sharding/cpg/tree/experiments/gin-regression-repair-results-b72-20261110/review/gin-regression-repair-20261110','This diagnostic: https://github.com/pg-sharding/cpg/tree/experiments/gin-or-startup-diagnostic-b72-20261110/review/gin-regression-repair-20261110/diagnostic-r4','', '[1] https://www.postgresql.org/message-id/52F36245.6070006%40vmware.com','[2] https://www.postgresql.org/message-id/10afd923-38f4-451c-af89-34f8654533cb%40googlemail.com','']
(r/'email-draft-UNSENT.txt').write_text('\n'.join(draft))
print('reports written')
